CREATE OR REPLACE FUNCTION public.bump_account_balance_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  NEW.balance_version := OLD.balance_version + CASE WHEN NEW.balance IS DISTINCT FROM OLD.balance THEN 1 ELSE 0 END;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.calculate_next_due_date(p_current_date date, p_frequency character varying, p_day_of_month integer DEFAULT NULL::integer, p_day_of_week integer DEFAULT NULL::integer, p_month_of_year integer DEFAULT NULL::integer)
 RETURNS date
 LANGUAGE plpgsql
AS $function$
DECLARE
    next_date DATE;
BEGIN
    CASE p_frequency
        WHEN 'daily' THEN
            next_date := p_current_date + INTERVAL '1 day';

        WHEN 'weekly' THEN
            IF p_day_of_week IS NOT NULL THEN
                next_date := p_current_date + INTERVAL '1 week';
                -- Adjust to correct day of week if needed
                next_date := next_date + (p_day_of_week - EXTRACT(DOW FROM next_date))::INTEGER;
            ELSE
                next_date := p_current_date + INTERVAL '1 week';
            END IF;

        WHEN 'monthly' THEN
            IF p_day_of_month IS NOT NULL THEN
                next_date := (p_current_date + INTERVAL '1 month')::DATE;
                -- Adjust day of month, handling month-end cases
                BEGIN
                    next_date := DATE_TRUNC('month', next_date) + (p_day_of_month - 1) * INTERVAL '1 day';
                EXCEPTION WHEN OTHERS THEN
                    -- If day doesn't exist in month, use last day of month
                    next_date := (DATE_TRUNC('month', next_date) + INTERVAL '1 month - 1 day')::DATE;
                END;
            ELSE
                next_date := p_current_date + INTERVAL '1 month';
            END IF;

        WHEN 'quarterly' THEN
            next_date := p_current_date + INTERVAL '3 months';

        WHEN 'yearly' THEN
            IF p_month_of_year IS NOT NULL AND p_day_of_month IS NOT NULL THEN
                next_date := DATE_TRUNC('year', p_current_date + INTERVAL '1 year') +
                           (p_month_of_year - 1) * INTERVAL '1 month' +
                           (p_day_of_month - 1) * INTERVAL '1 day';
            ELSE
                next_date := p_current_date + INTERVAL '1 year';
            END IF;

        ELSE
            RAISE EXCEPTION 'Invalid frequency: %', p_frequency;
    END CASE;

    RETURN next_date;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_association_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE expected_group uuid; actual_group uuid;
BEGIN
  IF TG_TABLE_NAME='account_users' THEN
    SELECT group_id INTO expected_group FROM public.accounts WHERE id=NEW.account_id FOR KEY SHARE;
  ELSIF TG_TABLE_NAME='recurring_users' THEN
    SELECT a.group_id INTO expected_group FROM public.recurring_transactions r JOIN public.accounts a ON a.id=r.account_id WHERE r.id=NEW.recurring_id FOR KEY SHARE OF r,a;
  ELSE
    SELECT group_id INTO expected_group FROM public.budgets WHERE id=NEW.budget_id FOR KEY SHARE;
    SELECT group_id INTO actual_group FROM public.categories WHERE key=NEW.category_key FOR KEY SHARE;
    IF actual_group='00000000-0000-0000-0000-000000000000'::uuid THEN RETURN NEW; END IF;
  END IF;
  IF TG_TABLE_NAME IN ('account_users','recurring_users') THEN
    SELECT group_id INTO actual_group FROM public.users WHERE id=NEW.user_id FOR KEY SHARE;
  END IF;
  IF expected_group IS NULL OR actual_group IS DISTINCT FROM expected_group THEN
    RAISE EXCEPTION 'Association outside authorized group' USING ERRCODE='23503';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.guard_category_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  -- The parent group's removal already owns the lifecycle of its cascading data.
  IF pg_trigger_depth() > 1 AND NOT EXISTS (SELECT 1 FROM public.groups WHERE id = OLD.group_id) THEN RETURN OLD; END IF;
  IF EXISTS (SELECT 1 FROM public.category_reference_keys(NULL) WHERE category_key = OLD.key) THEN
    RAISE EXCEPTION 'CATEGORY_IN_USE' USING ERRCODE = '23503';
  END IF;
  RETURN OLD;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_category_reference()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  reference_keys text[];
  reference_key text;
  current_row jsonb := to_jsonb(NEW);
  previous_row jsonb := CASE WHEN TG_OP = 'UPDATE' THEN to_jsonb(OLD) ELSE NULL END;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF TG_TABLE_NAME = 'budgets' AND (current_row->'categories') IS NOT DISTINCT FROM (previous_row->'categories') THEN RETURN NEW; END IF;
    IF TG_TABLE_NAME = 'budget_periods' AND (current_row->'budgets_snapshot') IS NOT DISTINCT FROM (previous_row->'budgets_snapshot') AND (current_row->'category_spending') IS NOT DISTINCT FROM (previous_row->'category_spending') THEN RETURN NEW; END IF;
    IF TG_TABLE_NAME NOT IN ('budgets', 'budget_periods', 'bank_connections') AND (current_row->>'category') IS NOT DISTINCT FROM (previous_row->>'category') THEN RETURN NEW; END IF;
  END IF;
  IF TG_TABLE_NAME = 'budgets' THEN
    SELECT array_agg(k) INTO reference_keys FROM jsonb_array_elements_text((current_row->'categories')) k;
  ELSIF TG_TABLE_NAME = 'budget_periods' THEN
    SELECT array_agg(k) INTO reference_keys FROM (
      SELECT jsonb_object_keys(coalesce(nullif(current_row->'category_spending', 'null'::jsonb), '{}'::jsonb)) k
      UNION SELECT jsonb_array_elements_text(coalesce(b->'categories', '[]'::jsonb)) FROM jsonb_array_elements(coalesce(nullif(current_row->'budgets_snapshot', 'null'::jsonb), '[]'::jsonb)) b
    ) keys;
  ELSE
    reference_keys := ARRAY[(current_row->>'category')];
  END IF;
  -- Same ordering for multiple keys. KEY SHARE conflicts with category deletion.
  FOR reference_key IN SELECT DISTINCT k FROM unnest(reference_keys) k WHERE k IS NOT NULL AND k <> '' ORDER BY k LOOP
    PERFORM 1 FROM public.categories WHERE key = reference_key FOR KEY SHARE;
    IF NOT FOUND THEN
      -- Archiving existing references is not the creation of a new reference.
      -- Keep legacy IDs/deleted keys verbatim, but only from this owner's
      -- persisted budget or from this very period's previous snapshot.
      IF TG_TABLE_NAME = 'budget_periods' THEN
        IF TG_OP = 'UPDATE'
          AND (current_row->>'user_id') IS NOT DISTINCT FROM (previous_row->>'user_id')
          AND (current_row->>'group_id') IS NOT DISTINCT FROM (previous_row->>'group_id')
          AND (
            coalesce(previous_row->'category_spending', '{}'::jsonb) ? reference_key
            OR EXISTS (
              SELECT 1 FROM jsonb_array_elements(coalesce(nullif(previous_row->'budgets_snapshot', 'null'::jsonb), '[]'::jsonb)) item
              WHERE (item->'categories') ? reference_key
            )
          ) THEN CONTINUE;
        END IF;
        IF EXISTS (
          SELECT 1
          FROM jsonb_array_elements(coalesce(nullif(current_row->'budgets_snapshot', 'null'::jsonb), '[]'::jsonb)) item
          JOIN public.budgets live ON live.id::text = item->>'id'
          WHERE live.user_id = (current_row->>'user_id')::uuid
            AND live.group_id = coalesce(
              (current_row->>'group_id')::uuid,
              (SELECT u.group_id FROM public.users u WHERE u.id = (current_row->>'user_id')::uuid)
            )
            AND live.categories ? reference_key
            AND (item->'categories') ? reference_key
        ) THEN CONTINUE;
        END IF;
      END IF;
      RAISE EXCEPTION 'Category reference is unavailable' USING ERRCODE = '23503';
    END IF;
  END LOOP;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_financial_category_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE target_group uuid; category_group uuid;
BEGIN
  IF NEW.category IS NULL OR NEW.category='' THEN RETURN NEW; END IF;
  IF TG_TABLE_NAME='recurring_transactions' THEN
    SELECT group_id INTO target_group FROM public.accounts WHERE id=NEW.account_id FOR KEY SHARE;
  ELSE target_group:=NEW.group_id; END IF;
  SELECT group_id INTO category_group FROM public.categories WHERE key=NEW.category FOR KEY SHARE;
  IF category_group IS NULL OR category_group NOT IN(target_group,'00000000-0000-0000-0000-000000000000'::uuid) THEN
    RAISE EXCEPTION 'Category outside authorized group' USING ERRCODE='23503';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.guard_membership_group_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF NEW.group_id IS NOT DISTINCT FROM OLD.group_id THEN RETURN NEW; END IF;
  -- A parent group's cascade owns removal of all of its financial resources.
  IF NOT EXISTS(SELECT 1 FROM public.groups WHERE id=OLD.group_id) THEN RETURN NEW; END IF;
  IF TG_TABLE_NAME='users' THEN
    IF EXISTS(SELECT 1 FROM public.account_users x JOIN public.accounts a ON a.id=x.account_id WHERE x.user_id=OLD.id AND a.group_id IS DISTINCT FROM NEW.group_id)
      OR EXISTS(SELECT 1 FROM public.recurring_users x JOIN public.recurring_transactions r ON r.id=x.recurring_id JOIN public.accounts a ON a.id=r.account_id WHERE x.user_id=OLD.id AND a.group_id IS DISTINCT FROM NEW.group_id) THEN
      RAISE EXCEPTION 'User still owns resources in the previous group' USING ERRCODE='23503';
    END IF;
  ELSE
    IF EXISTS(SELECT 1 FROM public.budget_categories x JOIN public.budgets b ON b.id=x.budget_id WHERE x.category_key=OLD.key AND NEW.group_id NOT IN (b.group_id,'00000000-0000-0000-0000-000000000000'::uuid)) THEN
      RAISE EXCEPTION 'Category still referenced in the previous group' USING ERRCODE='23503';
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.sync_legacy_associations()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF TG_TABLE_NAME='accounts' THEN
    DELETE FROM public.account_users WHERE account_id=NEW.id;
    INSERT INTO public.account_users SELECT NEW.id,x.id,x.position FROM unnest(NEW.user_ids) WITH ORDINALITY x(id,position);
  ELSIF TG_TABLE_NAME='recurring_transactions' THEN
    DELETE FROM public.recurring_users WHERE recurring_id=NEW.id;
    INSERT INTO public.recurring_users SELECT NEW.id,x.id::uuid,x.position FROM unnest(NEW.user_ids) WITH ORDINALITY x(id,position);
  ELSE
    DELETE FROM public.budget_categories WHERE budget_id=NEW.id;
    INSERT INTO public.budget_categories SELECT NEW.id,x.key,x.position FROM jsonb_array_elements_text(NEW.categories) WITH ORDINALITY x(key,position);
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.sync_legacy_group_members()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  -- Stable lock order when a member moves between two groups.
  IF TG_OP = 'UPDATE' THEN
    PERFORM 1 FROM public.groups WHERE id IN (OLD.group_id,NEW.group_id) ORDER BY id FOR UPDATE;
  END IF;
  IF TG_OP <> 'INSERT' AND (TG_OP = 'DELETE' OR OLD.group_id IS DISTINCT FROM NEW.group_id) THEN
    UPDATE public.groups SET user_ids=array_remove(user_ids, OLD.id) WHERE id=OLD.group_id;
  END IF;
  IF TG_OP <> 'DELETE' AND (TG_OP = 'INSERT' OR OLD.group_id IS DISTINCT FROM NEW.group_id) THEN
    UPDATE public.groups SET user_ids=CASE WHEN NEW.id=ANY(user_ids) THEN user_ids ELSE array_append(user_ids,NEW.id) END WHERE id=NEW.group_id;
  END IF;
  RETURN COALESCE(NEW,OLD);
END $function$

CREATE OR REPLACE FUNCTION public.update_account_balance(p_account_id uuid, p_delta numeric)
 RETURNS numeric
 LANGUAGE plpgsql
AS $function$
DECLARE
  new_balance NUMERIC;
BEGIN
  UPDATE accounts
  SET balance = COALESCE(balance, 0) + p_delta,
      updated_at = NOW()
  WHERE id = p_account_id
  RETURNING balance INTO new_balance;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Account not found: %', p_account_id;
  END IF;

  RETURN new_balance;
END;
$function$

